# AIoT Smart Conducting Performance System
# Track: Shape of You (user-supplied MIDI arrangement)
# Generated from MIDI format 1, 16 source tracks, 960 ticks per beat.
# Source timing: 192 BPM in 2/2; normalized timing: 96 BPM.
# Loop length: 374 Sonic Pi beats.
# Duplicate source tracks 10, 14 and 15 were omitted.
#
# Styles:
#   acoustic_pop   - piano and plucked textures, restrained percussion
#   tropical_house - bright plucks, bells, rounded bass and full groove
#   festival_edm  - supersaw lead, stronger bass and drums
#
# Layer contract:
#   1 / melody  - primary melody
#   2 / harmony - hook, chords and backing parts
#   3 / bass    - low register part
#   4 / rhythm  - percussion, handclaps and woodblock
#
# OSC input (backend -> Sonic Pi, UDP 4560):
#   /conductor/transport command_id action
#   /conductor/state command_id bpm master_amp drum_amp drum_density bass_amp harmony_amp melody_amp energy reverb_mix cutoff [style]
#   /conductor/bpm command_id bpm
#   /conductor/volume command_id volume
#   /conductor/style command_id style
#   /conductor/layer command_id layer enabled
#
# OSC feedback (Sonic Pi -> backend, UDP 4561):
#   /music/beat, /music/bar, /music/state, /music/ack
#   /music/style, /music/layers
#
# Open run_shape_of_you.rb in Sonic Pi instead of opening this large file.

use_debug false
use_cue_logging false
use_osc "127.0.0.1", 4561
set_sched_ahead_time! 0.75

set :playing, true
set :current_bpm, 96
set :target_bpm, 96
set :master_amp, 0.44
set :target_master_amp, 0.44
set :current_style, :acoustic_pop
set :beat_count, 0
set :bar_count, 0
set :track_id, :shape_of_you
set :layer_melody, true
set :layer_harmony, true
set :layer_bass, true
set :layer_rhythm, true
set :command_results, []

style_order = [:acoustic_pop, :tropical_house, :festival_edm]
loop_beats = 374

define :clamp_value do |value, low, high|
  [[value.to_f, low].max, high].min
end

define :approach_value do |current, target, amount|
  current.to_f + ((target.to_f - current.to_f) * amount.to_f)
end

define :cached_command_result do |command_id|
  command_text = command_id.to_s
  match = (get(:command_results) || []).find do |entry|
    entry[0] == command_text
  end
  match ? match[1] : nil
end

define :finish_command do |command_id, result|
  command_text = command_id.to_s
  result_text = result.to_s
  recent = (get(:command_results) || []).reject do |entry|
    entry[0] == command_text
  end
  set :command_results, ([[command_text, result_text]] + recent)[0, 32]
  osc "/music/ack", command_text, result_text
end

define :wait_until_playing do
  while get(:playing) != true
    sleep 0.05
  end
end

define :wait_music_beats do |beats|
  remaining = [beats.to_f, 0.0].max
  while remaining > 0.0001
    if get(:playing) == true
      use_bpm get(:current_bpm).to_f
      # Poll once per beat at most. The previous 1/16-beat polling caused
      # hundreds of scheduler wake-ups per second across all MIDI tracks.
      step = [remaining, 1.0].min
      sleep step
      remaining = remaining - step
    else
      sleep 0.05
    end
  end
end

define :layer_enabled_for_role do |role|
  if role == :melody
    get(:layer_melody) == true
  elsif role == :bass
    get(:layer_bass) == true
  elsif role == :rhythm
    get(:layer_rhythm) == true
  else
    get(:layer_harmony) == true
  end
end

define :voice_config do |role|
  style = get(:current_style)
  config = [:beep, 0.20, 0.8, 0, 0.0]

  if style == :acoustic_pop
    if role == :melody
      config = [:piano, 0.34, 0.92, 0, -0.06]
    elsif role == :hook
      config = [:pluck, 0.20, 0.58, 0, 0.10]
    elsif role == :harmony
      config = [:piano, 0.15, 0.82, 0, -0.12]
    elsif role == :bass
      config = [:fm, 0.22, 0.72, 12, 0.0]
    end
  elsif style == :festival_edm
    if role == :melody
      config = [:supersaw, 0.28, 0.60, 0, -0.06]
    elsif role == :hook
      config = [:dsaw, 0.20, 0.50, 0, 0.10]
    elsif role == :harmony
      config = [:prophet, 0.16, 0.68, 0, -0.12]
    elsif role == :bass
      config = [:tb303, 0.24, 0.56, 12, 0.0]
    end
  else
    if role == :melody
      config = [:pluck, 0.30, 0.72, 0, -0.06]
    elsif role == :hook
      config = [:pretty_bell, 0.20, 0.64, 0, 0.10]
    elsif role == :harmony
      config = [:prophet, 0.15, 0.78, 0, -0.12]
    elsif role == :bass
      config = [:fm, 0.26, 0.64, 12, 0.0]
    end
  end

  config
end

define :play_voice_event do |role, note_value, duration, velocity|
  if layer_enabled_for_role role
    synth_name, role_amp, release_scale, transpose, pan_value = voice_config role
    release_value = [[duration.to_f * release_scale.to_f, 0.05].max, 5.0].min
    use_synth synth_name
    amp_value = clamp_value(velocity, 0.04, 1.0) * role_amp.to_f * get(:master_amp).to_f
    play note_value.to_i + transpose.to_i,
         attack: 0.005,
         release: release_value,
         amp: amp_value,
         pan: pan_value.to_f
  end
end

define :play_rhythm_event do |note_value, velocity|
  if get(:layer_rhythm) == true
    style = get(:current_style)
    midi_note = note_value.to_i
    allowed = true

    if [35, 36].include?(midi_note)
      sample_name = :bd_haus
    elsif [37].include?(midi_note)
      sample_name = :perc_snap
    elsif [38, 40].include?(midi_note)
      sample_name = :sn_dub
    elsif [39].include?(midi_note)
      sample_name = :perc_snap2
    elsif [42, 44].include?(midi_note)
      sample_name = :drum_cymbal_closed
    elsif [45].include?(midi_note)
      sample_name = :drum_tom_lo_soft
    elsif midi_note >= 60
      sample_name = :elec_tick
    else
      sample_name = :drum_tom_mid_soft
    end

    if style == :acoustic_pop
      allowed = [35, 36, 37, 38, 39, 40, 42, 44, 45].include?(midi_note) ||
                midi_note >= 60
      style_amp = 0.42
      cutoff_value = 104
    elsif style == :festival_edm
      style_amp = 0.68
      cutoff_value = 125
    else
      style_amp = 0.52
      cutoff_value = 110
    end

    if allowed
      amp_value = clamp_value(velocity, 0.04, 1.0) * style_amp * get(:master_amp).to_f
      sample sample_name, amp: amp_value, cutoff: cutoff_value
    end
  end
end

define :perform_event_track do |events, role, total_beats|
  cursor = 0.0
  events.each do |event|
    start_beat, duration, note_value, velocity = event
    wait_music_beats start_beat.to_f - cursor
    wait_until_playing
    if role == :rhythm
      play_rhythm_event note_value, velocity
    else
      play_voice_event role, note_value, duration, velocity
    end
    cursor = start_beat.to_f
  end
  wait_music_beats total_beats.to_f - cursor
end

define :report_state do
  osc "/music/state",
      get(:playing) == true ? 1 : 0,
      get(:current_bpm).to_f.round(1),
      "shape_of_you",
      0.68
end

define :report_layers do
  osc "/music/layers",
      get(:layer_melody) == true ? 1 : 0,
      get(:layer_harmony) == true ? 1 : 0,
      get(:layer_bass) == true ? 1 : 0,
      get(:layer_rhythm) == true ? 1 : 0
end

